"""Initial program for the suite task; SCiEL evolves the EVOLVE-BLOCK."""
# EVOLVE-BLOCK-START
import time
from itertools import combinations

def _pgl2_11_generators():
    """
    Generate the PGL(2,11) group acting on 12 points (0..10, 11=infinity).
    PGL(2,11) has order 1320 = 11*120. We represent elements as (a,b,c,d)
    where x -> (a*x+b)/(c*x+d) mod 11, with infinity handled specially.
    """
    p = 11
    # We'll generate the group by BFS from identity using standard generators
    # PGL(2,p) is generated by:
    #   T: x -> x+1  (translation)
    #   M: x -> -x   (inversion)
    #   S: x -> x/p  (scaling by primitive root)
    # Actually for PGL(2,11), generators are:
    #   A: x -> x+1
    #   B: x -> -x
    #   C: x -> 2x (or any non-square scaling)
    
    # Represent each group element as a tuple (a,b,c,d) mod 11
    # where the transformation is x -> (a*x+b)/(c*x+d)
    # Special case: if c*x+d == 0, then x maps to infinity (11)
    # If x is infinity, it maps to a/c if c!=0, else infinity
    
    def apply_transform(el, x):
        """Apply Möbius transformation el=(a,b,c,d) to point x in 0..11."""
        a, b, c, d = el
        if x == 11:  # infinity
            if c == 0:
                return 11
            else:
                return (a * pow(c, p-2, p)) % p
        else:
            denom = (c * x + d) % p
            if denom == 0:
                return 11
            else:
                num = (a * x + b) % p
                return (num * pow(denom, p-2, p)) % p
    
    def compose(el1, el2):
        """Compose el1 after el2: apply el2 first, then el1."""
        a1, b1, c1, d1 = el1
        a2, b2, c2, d2 = el2
        # el1 ∘ el2: x -> (a1*(a2*x+b2)/(c2*x+d2) + b1) / (c1*(a2*x+b2)/(c2*x+d2) + d1)
        # = (a1*(a2*x+b2) + b1*(c2*x+d2)) / (c1*(a2*x+b2) + d1*(c2*x+d2))
        # Numerator: (a1*a2 + b1*c2)*x + (a1*b2 + b1*d2)
        # Denominator: (c1*a2 + d1*c2)*x + (c1*b2 + d1*d2)
        a = (a1 * a2 + b1 * c2) % p
        b = (a1 * b2 + b1 * d2) % p
        c = (c1 * a2 + d1 * c2) % p
        d = (c1 * b2 + d1 * d2) % p
        return (a, b, c, d)
    
    # Identity
    identity = (1, 0, 0, 1)
    
    # Standard generators for PGL(2,11):
    # T: x -> x+1 => (1,1,0,1)
    T = (1, 1, 0, 1)
    # M: x -> -x => (1,0,0,-1) = (1,0,0,10) mod 11
    M = (1, 0, 0, 10)
    # S: x -> 2x => (2,0,0,1)
    S = (2, 0, 0, 1)
    
    # BFS to generate full group
    group = {identity}
    queue = [identity]
    while queue:
        g = queue.pop(0)
        for gen in [T, M, S]:
            new_g = compose(gen, g)
            if new_g not in group:
                group.add(new_g)
                queue.append(new_g)
    
    return list(group), apply_transform

def construct():
    """
    Construct the Witt design S(5,6,12) by generating the PGL(2,11) orbit
    of a single base 6-subset.
    
    The 132 blocks of S(5,6,12) form a single orbit under PGL(2,11) acting
    on the 12 points {0,...,10,∞}. We find a base block whose orbit has
    size 132 (i.e., stabilizer of size 1320/132 = 10).
    """
    start_time = time.time()
    deadline = start_time + 120  # Safety margin
    
    # Generate PGL(2,11) group
    group, apply_transform = _pgl2_11_generators()
    
    # Try to find a base 6-subset whose PGL(2,11) orbit has exactly 132 distinct blocks
    # and satisfies the Steiner property (no 5-subset repeated)
    
    # Known fact: {0,1,3,4,5,9} or similar small-index sets work.
    # Let's try several candidate base blocks.
    
    candidates = [
        frozenset([0, 1, 3, 4, 5, 9]),
        frozenset([0, 1, 2, 4, 5, 6]),
        frozenset([0, 1, 3, 5, 8, 10]),
        frozenset([0, 2, 3, 5, 6, 8]),
        frozenset([0, 1, 2, 3, 4, 5]),
        frozenset([0, 1, 3, 4, 6, 10]),
        frozenset([0, 2, 4, 5, 7, 9]),
        frozenset([0, 1, 2, 4, 7, 8]),
    ]
    
    for base in candidates:
        if time.time() > deadline - 10:
            break
        
        # Generate orbit of base under PGL(2,11)
        orbit = set()
        for g in group:
            block = frozenset(apply_transform(g, x) for x in base)
            orbit.add(block)
        
        if len(orbit) != 132:
            continue
        
        # Check Steiner property: no 5-subset appears in two blocks
        covered_5sets = set()
        valid = True
        for block in orbit:
            for five in combinations(sorted(block), 5):
                if five in covered_5sets:
                    valid = False
                    break
                covered_5sets.add(five)
            if not valid:
                break
        
        if valid:
            # Success! Return the 132 blocks
            return [list(b) for b in sorted(orbit, key=lambda x: tuple(sorted(x)))]
    
    # Fallback: if no candidate worked, do a randomized greedy search
    # This should not happen, but provides safety
    import random
    best_blocks = []
    
    for attempt in range(50):
        if time.time() > deadline - 5:
            break
        
        random.seed(attempt)
        covered = set()
        blocks = []
        
        # Generate all 6-subsets and shuffle
        all_blocks = list(combinations(range(12), 6))
        random.shuffle(all_blocks)
        
        for b in all_blocks:
            subsets = list(combinations(b, 5))
            if not any(s in covered for s in subsets):
                blocks.append(list(b))
                covered.update(subsets)
        
        if len(blocks) > len(best_blocks):
            best_blocks = blocks
    
    return best_blocks
# EVOLVE-BLOCK-END
